function DataPreview({title,rows=[]}) {
 const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];
 return <section><h3 className="font-bold mb-2">{title}</h3><div className="overflow-auto max-h-80"><table className="w-full text-xs text-left"><thead><tr>{cols.map(c=><th className="p-2 border border-slate-700" key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{cols.map(c=><td className="p-2 border border-slate-700" key={c}>{String(r[c]??'')}</td>)}</tr>)}</tbody></table></div></section>;
}
function CleaningLog({result}) {
 const [page,setPage]=useState(0);
 useEffect(()=>setPage(0),[result.runId]);
 const rows=[...(result.transformationTrace||[]).map(t=>({...t,status:'Changed'})),...(result.issues||[]).map(i=>({...i,status:'Review',action:i.issue}))].sort((a,b)=>a.row-b.row);
 const pages=Math.max(1,Math.ceil(rows.length/25));
 return <section className="space-y-3"><h3 className="font-bold">Cleaning log</h3><div className="flex gap-4"><a className="text-cyan-300 underline" href={`${API}/runs/${result.runId}/log`}>Export full log CSV</a><a className="text-cyan-300 underline" target="_blank" rel="noreferrer" href={`${API}/runs/${result.runId}/print`}>Print full log</a></div><div className="overflow-auto"><table className="w-full text-xs text-left"><thead><tr>{['Row','Field','Status','Before','After','Action / detection'].map(c=><th key={c} className="p-2 border border-slate-700">{c}</th>)}</tr></thead><tbody>{rows.slice(page*25,page*25+25).map((r,i)=><tr key={i}>{[r.row,r.field,r.status,r.before??'',r.after??'',r.action].map((v,j)=><td key={j} className="p-2 border border-slate-700">{String(v)}</td>)}</tr>)}</tbody></table>{!rows.length&&<p className="p-3">No changes or issues detected.</p>}</div><div className="flex items-center gap-4"><button disabled={page===0} onClick={()=>setPage(p=>p-1)} className="disabled:opacity-40">Previous</button><span>Entries {rows.length?page*25+1:0}–{Math.min(rows.length,page*25+25)} of {rows.length} · 25 per page</span><button disabled={page>=pages-1} onClick={()=>setPage(p=>p+1)} className="disabled:opacity-40">Next</button></div></section>;
}

import React,{useEffect,useState} from 'react';
import {Pencil,Plus,RefreshCw,X,Check,LoaderCircle} from 'lucide-react';
const API=import.meta.env.VITE_API_URL||'/api/v1';
const button='inline-flex items-center justify-center gap-1.5 rounded border border-slate-600 px-2.5 py-1.5 text-xs hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed';
const iconButton=button+' h-8 w-8 p-0 shrink-0 focus-visible:outline focus-visible:outline-2 focus-visible:outline-cyan-400';
const input='w-full rounded-lg bg-slate-950 border border-slate-700 p-2 text-sm';
const codes={RULE_FIELD_MISSING:'Configured field is missing',RULE_TARGET_EXISTS:'Rename target already exists',RULE_CONFIG_INVALID:'Rule configuration is invalid',RULE_EXECUTION_ERROR:'Rule execution failed',RULE_PROCESS_EXIT:'Worker stopped unexpectedly',RULE_VALIDATION_FAILED:'Data failed the rule checks',RULE_NUMERIC_INVALID:'Invalid numeric values',RULE_DATE_INVALID:'Invalid date values',VALIDATION_REQUIRED:'Required values are missing',VALIDATION_RANGE:'Values failed the allowed range',VALIDATION_PATTERN:'Values failed the text pattern',VALIDATION_DUPLICATE:'Duplicate values detected',RULE_RETRY_LIMIT:'Rule failed three attempts',INPUT_PARSE_ERROR:'Input file could not be parsed',JOB_TIMEOUT:'Job exceeded the processing time limit',JOB_CANCELLED_BY_USER:'Cancelled by user',JOB_SERVER_RESTARTED:'Server stopped before completion',JOB_INTERNAL_ERROR:'Job processing encountered an internal error'};
function stamp(value){return value?new Date(value).toLocaleString('en-GB',{timeZone:'Asia/Kuala_Lumpur',hour12:false}):'';}
function currentWeek(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const d=new Date(Date.UTC(+parts.year,+parts.month-1,+parts.day));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const first=new Date(Date.UTC(d.getUTCFullYear(),0,1));return `${d.getUTCFullYear()}-W${String(Math.ceil((((d-first)/86400000)+1)/7)).padStart(2,'0')}`;}
async function api(path,options){const response=await fetch(`${API}${path}`,options);const data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'Request failed.');return data;}
function ErrorCodes({values=[]}){return <div className="space-y-1 text-xs text-rose-300">{values.map(code=><div key={code}><span className="font-mono font-semibold">{code}</span> · {codes[code]||'Processing error'}</div>)}</div>;}
export default function BatchLogs({incomingFile,onFileAccepted}){
