 useEffect(()=>{if(incomingFile){setFile(incomingFile);setOpen(true);onFileAccepted?.();}},[incomingFile]);
 const filtered=jobs.filter(j=>`${j.retailer_name} ${j.period} ${j.status}`.toLowerCase().includes(filter.toLowerCase()));
