 useEffect(()=>setPage(p=>Math.min(p,totalPages-1)),[totalPages]);
 async function start(e){e.preventDefault();setError('');if(!file){setError('Select a data file.');return;}if(file.size>50*1024*1024){setError('Batch files must be below the 50 MB upload limit.');return;}setBusy(true);const form=new FormData();form.append('file',file);form.append('retailerId',retailerId);form.append('period',period);try{await api('/batches',{method:'POST',body:form});setOpen(false);setFile(null);setNotice('Batch started. Its current progress appears below.');await refresh();}catch(e){setError(e.message);}finally{setBusy(false);}}
 async function action(id,type){if(type==='cancel'&&!window.confirm('Cancel this job? The cancelled job will have no End Time or Audit Logs. A previous job is kept if this is a replacement attempt.'))return;setBusy(true);setError('');try{await api(`/batches/${id}/${type}`,{method:'POST'});setNotice(type==='reprocess'?'Reprocessing started using the latest saved retailer rules. The previous job remains until this attempt succeeds.':type==='approve'?'Job approved.':'Job cancelled.');await refresh();}catch(e){setError(e.message);}finally{setBusy(false);}}
