 return <div className="space-y-6" data-testid="batch-logs">
  <div className="flex flex-wrap justify-between items-start gap-3"><div><h2 className="text-2xl font-bold">Data Streams — Batch Job Log</h2><p className="text-sm text-slate-400 mt-2">One recorded job per retailer and ISO week. All times are shown in Malaysia time (UTC+8).</p></div><div className="flex gap-2"><button className={button} onClick={()=>refresh().catch(e=>setError(e.message))}><RefreshCw size={14}/>Refresh</button><button className={button+' bg-cyan-600'} onClick={()=>setOpen(true)}><Plus size={14}/>New Batch Job</button></div></div>
