n'].includes(job.status)&&<button disabled={busy||!!pending} className={iconButton+' text-emerald-300'} aria-label="Approve Job" title="Approve Job" onClick={()=>action(job.id,'approve')}><Check size={16} aria-hidden="true"/></button>}{job.status!=='Cancelled Job'&&!pending&&<button disabled={busy} className={iconButton+' text-rose-300'} aria-label="Cancel Job" title="Cancel Job" onClick={()=>action(job.id,'cancel')}><X size={16} aria-hidden="true"/></button>}{pending&&<span role="status" aria-label="Replacement processing" title="Replacement processing" className="inline-flex h-8 w-8 items-center justify-center text-cyan-300"><LoaderCircle size={16} className="animate-spin motion-reduce:animate-none" aria-hidden="true"/><span className="sr-only">Replacement processing</span></span>}</div></td><td className="p-3">{job.status!=='Cancelled Job'&&job.hasAudit&&<button aria-label={`Open audit for ${job.retailer_name} ${job.period}`} title="Open audit logs" className={iconButton} onClick={()=>showAudit(job.id)}><Pencil size={15} aria-hidden="true"/></button>}</td></tr>;})}</tbody></table>{!filtered.length&&<p className="text-sm text-slate-400 text-center p-6">No recorded batch jobs. Start a job with a saved retailer and week.</p>}</div><div className="flex justify-between items-center text-xs"><span>{filtered.length} recorded jobs · 25 rows per page</span><div className="flex gap-3 items-center"><button disabled={page===0} className={button} onClick={()=>setPage(p=>p-1)}>Previous</button><span>{page+1} / {totalPages}</span><button disabled={page>=totalPages-1} className={button} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></section>
