 return '<!doctype html><html><head><title>Cleaning log</title><style>body{font:12px Arial}table{border-collapse:collapse;width:100%}td,th{border:1px solid #aaa;padding:6px;overflow-wrap:anywhere}thead{display:table-header-group}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>DataFlow V1.3.A2 cleaning log</h1><p>'+escape(run['filename'])+' | '+escape(rid)+' | '+str(len(rows))+' entries</p><table><thead><tr><th>Row</th><th>Field</th><th>Status</th><th>Before</th><th>After</th><th>Action / detection</th></tr></thead><tbody>'+body+'</tbody></table></body></html>'

